function currParagraphs(s){const sentences=s.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[s],out=[];let p='';for(const x of sentences){if(p&&p.split(/\s+/).length+x.split(/\s+/).length>40){out.push(p.trim());p=''}p+=x}if(p.trim())out.push(p.trim());return out}
