// Leçon pas encore ouverte : cadenas à la place du numéro, sans flèche. L’explication est donnée une seule fois en haut du programme.
function currDisableLink(link){const locked=document.createElement('span');locked.className='curr-locked';locked.setAttribute('aria-disabled','true');locked.innerHTML=link.innerHTML;const [number,,arrow]=locked.children;const icon='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg><span class="curr-sr">Verrouillée : </span>';if(number){number.className='curr-lock';number.innerHTML=icon}else locked.insertAdjacentHTML('afterbegin','<span class="curr-lock">'+icon+'</span>');arrow?.remove();link.replaceWith(locked)}
function currUpdateProgressionUI(){if(aRoute.kind!=='apprendre'||aRoute.id!=='python-bases')return;if(aRoute.stepId){const lesson=currCurrentLesson();if(!lesson)return;if(currMode==='validation'){const aside=$('.curr-practice');if(aside)aside.hidden=true;$('.curr-mobile-tabs [data-curr="code"]')?.remove();const eyebrow=$('.curr-lesson-head .eyebrow');if(eyebrow)eyebrow.textContent='JE CONNAIS DÉJÀ · TEST DE 5 QUESTIONS';$('.curr-mobile-tabs')?.remove();const workspace=$('.curr-workspace');if(workspace)workspace.dataset.tab='read';for(const part of $$('.curr-reading>*'))if(part.id!=='curr-quiz')part.hidden=true;const quizTitle=$('#curr-quiz>h2');if(quizTitle)quizTitle.textContent='5 questions sur ce module';const instructions=$('.curr-footer>div>p');if(instructions)instructions.textContent='Réussis au moins 4 des 5 questions pour valider ce module. Tu peux recommencer autant de fois que nécessaire.'}else{const glossary=$('#curr-lexicon');if(glossary&&!$('.curr-reading-check')){const section=document.createElement('section');section.className='curr-reading-check';const button=document.createElement('button');button.type='button';button.className='secondary';button.dataset.curr='mark-read';button.textContent=state.curriculum.read[lesson.id]?'✓ Chapitre lu':'J’ai lu ce chapitre';button.disabled=state.curriculum.read[lesson.id]===true;section.append(button);glossary.after(section)}const instructions=$('.curr-footer>div>p');if(instructions)instructions.textContent='Pour continuer, marque ce chapitre comme lu et réponds correctement à toutes les questions du mini-quiz. Les exercices sont facultatifs ; tu peux réessayer les questions autant de fois que nécessaire.'}for(const link of $$('.curr-lesson-head details a')){const id=link.getAttribute('href')?.split('/').at(-1),linked=id&&currLesson(id);if(linked&&!currLessonUnlocked(linked))currDisableLink(link)}return}for(const link of $$('.curr-outline a')){const id=link.getAttribute('href')?.split('/').at(-1),lesson=id&&currLesson(id);if(lesson&&!currLessonUnlocked(lesson))currDisableLink(link)}for(const link of $$('.curr-module>a[href$="/validation"]')){const id=link.getAttribute('href')?.split('/').at(-2);if(id&&!currModuleUnlocked(id)){const note=document.createElement('span');note.className='curr-locked';note.setAttribute('aria-disabled','true');note.style.opacity='.65';note.textContent='Je connais déjà · verrouillé jusqu’à la fin du module précédent';link.replaceWith(note)}else link.textContent='Je connais déjà · test de 5 questions →'}}
const currRenderBeforeProgressionUI=render;render=function(){currRenderBeforeProgressionUI();currUpdateProgressionUI();currFrenchSpacing()};
window.addEventListener('click',event=>{const button=event.target.closest?.('[data-curr="mark-read"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const lesson=currLesson(aRoute.stepId);if(!lesson||currMode==='validation'||!currLessonUnlocked(lesson))return;state.curriculum.read[lesson.id]=true;aPersist();render()},true);

function currChapterEndEligible(lesson){return currMode!=='validation'&&!!lesson?.chapter_end}
function currChapterEndCorrect(lesson,answer){return answer===lesson.chapter_end.answer}
function currUpdateChapterEndUI(){
 if(aRoute.kind!=='apprendre'||aRoute.id!=='python-bases'||!aRoute.stepId)return;
 const lesson=currLesson(aRoute.stepId),anchor=$('.curr-reading-check');
 if(!currChapterEndEligible(lesson)||!anchor||!currLessonUnlocked(lesson))return;
 const saved=state.curriculum.chapterEnd[lesson.id]||{answer:null,checked:false,ownWords:'',modelShown:false};
 let section=$('#curr-chapter-end');
 if(!section){
  section=document.createElement('section');
  section.id='curr-chapter-end';
  section.className='curr-chapter-end';
  section.innerHTML=`<h2>Pour terminer ce chapitre</h2><fieldset><legend>${esc(lesson.chapter_end.question)}</legend>${lesson.chapter_end.options.map((option,index)=>`<label><input type="radio" name="curr-chapter-end-answer" value="${index}"> ${esc(option)}</label>`).join('')}</fieldset><button type="button" class="secondary" data-chapter-end-check>Vérifier ma réponse</button><p class="curr-chapter-end-result" role="status" hidden></p><div class="curr-chapter-end-reflection" hidden><label for="curr-chapter-end-words">Explique ce que tu as compris avec tes propres mots <span>(facultatif)</span></label><textarea id="curr-chapter-end-words" maxlength="2000" rows="4" placeholder="Écris quelques phrases, si tu le souhaites."></textarea><button type="button" class="secondary" data-chapter-end-model>Voir l’explication de référence</button><p class="curr-chapter-end-model" hidden>${esc(lesson.chapter_end.explanation)}</p></div>`;
  anchor.after(section);
 }
 const choices=$$('input[name="curr-chapter-end-answer"]',section);
 for(const choice of choices)choice.checked=saved.answer===Number(choice.value);
 const check=section.querySelector('[data-chapter-end-check]');
 check.disabled=saved.answer===null||saved.checked;
 const result=section.querySelector('.curr-chapter-end-result');
 result.hidden=!saved.checked;
 if(saved.checked)result.textContent=currChapterEndCorrect(lesson,saved.answer)?'Bonne réponse.':'Ce n’est pas la bonne réponse. Relis le chapitre, puis réessaie.';
 const reflection=section.querySelector('.curr-chapter-end-reflection');
 reflection.hidden=!saved.checked;
 section.querySelector('#curr-chapter-end-words').value=saved.ownWords;
 section.querySelector('.curr-chapter-end-model').hidden=!saved.modelShown;
}
const currRenderBeforeChapterEndUI=render;
render=function(){currRenderBeforeChapterEndUI();currUpdateChapterEndUI()};
window.addEventListener('change',event=>{
 const choice=event.target.closest?.('input[name="curr-chapter-end-answer"]');
 if(!choice)return;
 event.stopImmediatePropagation();
 const lesson=currLesson(aRoute.stepId);
 if(!currChapterEndEligible(lesson)||!currLessonUnlocked(lesson))return;
 state.curriculum.chapterEnd[lesson.id]={answer:Number(choice.value),checked:false,ownWords:state.curriculum.chapterEnd[lesson.id]?.ownWords||'',modelShown:false};
 aPersist();
 const section=$('#curr-chapter-end');
 section.querySelector('[data-chapter-end-check]').disabled=false;
 section.querySelector('.curr-chapter-end-result').hidden=true;
 section.querySelector('.curr-chapter-end-reflection').hidden=true;
 section.querySelector('.curr-chapter-end-model').hidden=true;
},true);
window.addEventListener('input',event=>{
 if(!event.target.matches?.('#curr-chapter-end-words'))return;
 const lesson=currLesson(aRoute.stepId);
 if(!currChapterEndEligible(lesson))return;
 const progress=state.curriculum.chapterEnd[lesson.id];
 if(progress){progress.ownWords=event.target.value.slice(0,2000);aPersist()}
},true);
window.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-chapter-end-check],[data-chapter-end-model]');
 if(!button)return;
 event.preventDefault();
 event.stopImmediatePropagation();
 const lesson=currLesson(aRoute.stepId);
 if(!currChapterEndEligible(lesson)||!currLessonUnlocked(lesson))return;
 const progress=state.curriculum.chapterEnd[lesson.id];
 if(!progress)return;
 if(button.matches('[data-chapter-end-check]')){
  if(progress.answer===null)return;
  progress.checked=true;
  aPersist();
  currUpdateChapterEndUI();
 }else if(progress.checked){
  progress.modelShown=true;
  aPersist();
  $('#curr-chapter-end .curr-chapter-end-model').hidden=false;
 }
},true);
// Sur téléphone, le résultat de « Vérifier mon code » peut se trouver sous l’écran : on l’amène dans la zone visible.
function currRevealResult(){requestAnimationFrame(()=>{const r=$('#curr-result');if(!r)return;const behavior=matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',b=r.getBoundingClientRect(),panel=r.closest('.curr-practice');if(panel&&getComputedStyle(panel).position==='sticky'){const pr=panel.getBoundingClientRect();if(b.top<pr.top||b.bottom>pr.bottom)panel.scrollBy({top:b.top-pr.top-pr.height/3,behavior});return}const bottomBar=$('.bottom-nav')?.getBoundingClientRect().height||0;if(b.top<0||b.bottom>innerHeight-bottomBar-16)r.scrollIntoView({block:'center',behavior})})}
// La loupe ouvre la recherche avec le curseur déjà dans le champ (le champ peut apparaître après le chargement des données).
var currFocusSearch=false;
function currFocusSearchField(tries=0){requestAnimationFrame(()=>{const input=$('#curr-search');if(input){currFocusSearch=false;input.focus();input.setSelectionRange(input.value.length,input.value.length);return}if(tries<60&&aRoute.kind==='recherche')currFocusSearchField(tries+1);else currFocusSearch=false})}
// Recherche vide : quelques idées plutôt que quatre cartes « Entre un mot pour chercher ».
function currSearchSuggestions(){return `<section class="panel"><h2>Quelques idées pour commencer</h2><p>Tape un mot, ou essaie une de ces recherches :</p><ul class="curr-search-suggestions">${['boucle','variable','condition','print','FCFA'].map(w=>`<li><a href="#/recherche/${encodeURIComponent(w)}">${esc(w)}</a></li>`).join('')}</ul><p><a class="text-button" href="#/bibliotheque">Consulter aussi la bibliothèque de référence →</a></p></section>`}
// Typographie française dans les titres : espace insécable avant ? ! : ; » et après «, pour qu’un « ? » ne se retrouve pas seul sur une ligne.
function currFrenchSpacing(){if(state.lang==='en')return;for(const el of $$('main :is(h1,h2,h3,legend)')){const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const text=node.nodeValue.replace(/ ([?!:;»])/g,'\u00a0$1').replace(/« /g,'«\u00a0');if(text!==node.nodeValue)node.nodeValue=text}}}
